55:   try {
56:     const { data } = await request('/models', {}, fetchImpl);
57:     const model = data?.find(item => item.id === MODEL);
58:     const promptPrice = Number(model?.pricing?.prompt);
59:     const completionPrice = Number(model?.pricing?.completion);
60:     // Deliberately conservative caps, not a general-purpose cost reservation system.
61:     if (!model || !Number.isFinite(promptPrice) || promptPrice < 0 || promptPrice > 0.5 / 1e6
62:       || !Number.isFinite(completionPrice) || completionPrice < 0 || completionPrice > 1.5 / 1e6
63:       || Number(model.pricing.request ?? 0) !== 0) {
64:       throw new Error('Model unavailable or pricing exceeds the seed’s budget caps. Human review required.');
65:     }
66:     const messages = [
67:       { role: 'system', content: instructions },
68:       { role: 'user', content: objective },
